-- Public form templates catalog (global or team-scoped).
-- teamId NULL = available to every team.
-- profession_health_plan is scoped to Kathrein Antunes (exclusive draft/CTA).

CREATE TABLE IF NOT EXISTS "public"."corretor_studio_public_form_templates" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "slug" character varying(80) NOT NULL,
  "name" text NOT NULL,
  "description" text,
  "formKind" character varying(40) NOT NULL DEFAULT 'standard',
  "draft" jsonb NOT NULL,
  "sortOrder" integer NOT NULL DEFAULT 0,
  "isActive" boolean NOT NULL DEFAULT true,
  "teamId" uuid,
  "createdAt" timestamp(6) with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" timestamp(6) with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "corretor_studio_public_form_templates_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "corretor_studio_public_form_templates_slug_key" UNIQUE ("slug"),
  CONSTRAINT "corretor_studio_public_form_templates_teamId_fkey"
    FOREIGN KEY ("teamId") REFERENCES public.corretor_studio_teams(id)
    ON UPDATE CASCADE ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS "corretor_studio_public_form_templates_isActive_sortOrder_idx"
  ON public.corretor_studio_public_form_templates USING btree ("isActive", "sortOrder");

CREATE INDEX IF NOT EXISTS "corretor_studio_public_form_templates_teamId_isActive_sortO_idx"
  ON public.corretor_studio_public_form_templates USING btree ("teamId", "isActive", "sortOrder");

ALTER TABLE public.corretor_studio_public_form_templates ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON TABLE public.corretor_studio_public_form_templates FROM anon, authenticated;
GRANT ALL ON TABLE public.corretor_studio_public_form_templates TO service_role;

DROP POLICY IF EXISTS public_form_templates_service_role_all ON public.corretor_studio_public_form_templates;
CREATE POLICY public_form_templates_service_role_all
  ON public.corretor_studio_public_form_templates FOR ALL TO service_role
  USING (true) WITH CHECK (true);

